import React, { useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

const DEFAULT_AVATAR = '/default-avatar.png';

function getFallbackAvatar(user) {
  if (user?.robloxUserId) {
    return `https://www.roblox.com/headshot-thumbnail/image?userId=${user.robloxUserId}&width=420&height=420&format=png`;
  }
  return DEFAULT_AVATAR;
}

const Header = ({ balance, notifications }) => {
  const location = useLocation();
  const navigate = useNavigate();
  const { user } = useAuth();
  const [showWalletModal, setShowWalletModal] = useState(false);
  const effectiveBalance = balance != null ? balance : user?.balance;

  const getPageTitle = () => {
    switch(location.pathname) {
      case '/coinflip':
        return 'Coinflip';
      case '/blackjack':
        return 'Blackjack';
      case '/leaderboard':
        return 'Leaderboard';
      case '/stats':
        return 'Statistics';
      case '/provably-fair':
        return 'Provably Fair';
      case '/profile':
        return 'Profile';
      case '/admin':
        return 'Admin Panel';
      default:
        return 'Dashboard';
    }
  };

  const handleWalletClick = () => {
    setShowWalletModal(true);
  };

  const handleProfileClick = () => {
    navigate('/profile');
  };

  const displayName = user?.robloxDisplayName || user?.displayName || user?.robloxUsername || 'Anonymous';
  const avatarSrc = user?.avatar || getFallbackAvatar(user);

  return (
    <header className="header">
      <div className="header-left">
        <h2>{getPageTitle()}</h2>
      </div>

      <div className="header-right">
        <div className="balance-display">
          {Number(effectiveBalance || 0).toLocaleString()} <span className="ampcoin-text">AMP</span>
        </div>

        <button className="wallet-btn btn btn-secondary" onClick={handleWalletClick}>
          Wallet
        </button>

        <span className="username" onClick={handleProfileClick} style={{cursor: 'pointer'}} title={user?.robloxUsername || ''}>
          {displayName}
        </span>

        <img 
          src={avatarSrc || DEFAULT_AVATAR} 
          alt={`${displayName} avatar`} 
          className="user-avatar"
          onClick={handleProfileClick}
          style={{cursor: 'pointer'}}
          onError={(e) => {
            const fb = getFallbackAvatar(user);
            if (e.target.src !== fb) e.target.src = fb;
            else if (e.target.src !== DEFAULT_AVATAR) e.target.src = DEFAULT_AVATAR;
          }}
        />

        <div className="notifications">
          <span className="notification-icon">🔔</span>
          {notifications && notifications.length > 0 && (
            <span className="notification-badge">{notifications.length}</span>
          )}
        </div>
      </div>

      {showWalletModal && (
        <div className="wallet-modal-overlay" onClick={() => setShowWalletModal(false)}>
          <div className="wallet-modal" onClick={(e) => e.stopPropagation()}>
            <div className="wallet-modal-header">
              <h2>Wallet & Inventory</h2>
              <button 
                className="modal-close-btn"
                onClick={() => setShowWalletModal(false)}
              >
                ×
              </button>
            </div>
            <div className="wallet-modal-content">
              <div className="inventory-section">
                <h3>Your Items</h3>
                <div className="inventory-grid">
                  {user?.inventory && user.inventory.length > 0 ? (
                    user.inventory.map((item) => (
                      <div key={item.id} className="inventory-item">
                        <div className="item-image">
                          <div className="default-item-icon">💎</div>
                        </div>
                        <div className="item-details">
                          <h4>{item.name}</h4>
                          <p className="item-value">{item.value} AMP</p>
                          <span className={`badge badge-${item.rarity}`}>
                            {item.rarity}
                          </span>
                        </div>
                      </div>
                    ))
                  ) : (
                    <div className="no-items">No items in your inventory</div>
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </header>
  );
};

export default Header;
